import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TheaterRevealProps = Record<string, any>;

// Helper component for Marquee Bulbs
const Bulb = ({ x, y, index, frame }: { x: number, y: number, index: number, frame: number }) => {
  // Chase flash effect
  const phase = Math.floor(frame / 4) % 3;
  const isLit = (index % 3) === phase;
  
  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        width: 16,
        height: 16,
        borderRadius: '50%',
        backgroundColor: isLit ? '#fffacd' : '#555555',
        boxShadow: isLit ? '0 0 10px 4px rgba(255, 223, 0, 0.8), 0 0 20px 8px rgba(255, 140, 0, 0.6)' : 'inset 0 2px 4px rgba(0,0,0,0.6)',
        transition: 'none'
      }}
    />
  );
};

const TheaterReveal: React.FC<TheaterRevealProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 6,
  wallColor = "#1a1a1a",
  frameBorderColor = "#6b0707",
  curtainPrimary = "#c91a1a",
  curtainDark = "#5c0101",
  marqueePrimary = "#8b0000",
  marqueeInner = "#fff8dc",
  goldAccent = "#d4af37",
}) => {

  {/* Load Google Fonts (Satisfies structural requirement even without text) */ }
  useFontLoader(["Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety variables
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Curtain Opening Progress (0 to 1)
  const p = interpolate(frame, [25, 75], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.inOut(Easing.ease)
  });

  // Calculate Left Curtain Dynamic Path
  const leftX_top = 540 - 390 * p;
  const leftX_tie = 540 - 460 * p;
  const leftX_bot = 540 - 290 * p;
  const leftX_cp1 = 540 - 390 * p;
  const leftX_cp2 = 540 - 460 * p;
  const leftPath = `M 0 0 L ${leftX_top} 0 Q ${leftX_cp1} 300, ${leftX_tie} 600 Q ${leftX_cp2} 800, ${leftX_bot} 1080 L 0 1080 Z`;

  // Calculate Right Curtain Dynamic Path
  const rightX_top = 540 + 390 * p;
  const rightX_tie = 540 + 460 * p;
  const rightX_bot = 540 + 290 * p;
  const rightX_cp1 = 540 + 390 * p;
  const rightX_cp2 = 540 + 460 * p;
  const rightPath = `M 1080 0 L ${rightX_top} 0 Q ${rightX_cp1} 300, ${rightX_tie} 600 Q ${rightX_cp2} 800, ${rightX_bot} 1080 L 1080 1080 Z`;

  // Inner gradient squash scale (simulates fabric folds getting tighter)
  const innerScaleX = 1 - 0.46 * p;

  const curtainGrad = `linear-gradient(90deg, ${curtainPrimary} 0%, ${curtainDark} 12%, ${curtainPrimary} 25%, ${curtainDark} 38%, ${curtainPrimary} 50%, ${curtainDark} 62%, ${curtainPrimary} 75%, ${curtainDark} 88%, ${curtainPrimary} 100%)`;

  // Marquee Entrance Animation
  const marqueeYSpring = spring({
    frame: frame - 60,
    fps,
    config: { damping: 14, stiffness: 80 }
  });
  const marqueeTranslateY = interpolate(marqueeYSpring, [0, 1], [400, 0]);

  // Generate Bulb Positions visually around the marquee
  const bulbs = useMemo(() => {
    const bArr = [];
    const w = 760; 
    const h = 260; 
    const bw = 16;
    
    // Top Row
    for(let i=0; i<24; i++) bArr.push({ x: 20 + i*((w-40-bw)/23), y: 16 });
    // Right Col
    for(let i=0; i<5; i++) bArr.push({ x: w - 20 - bw, y: 20 + bw + (i+1)*((h-40-bw*2)/6) });
    // Bottom Row
    for(let i=0; i<24; i++) bArr.push({ x: w - 20 - bw - i*((w-40-bw)/23), y: h - 16 - bw });
    // Left Col
    for(let i=0; i<5; i++) bArr.push({ x: 20, y: h - 20 - bw - (i+1)*((h-40-bw*2)/6) });
    
    return bArr;
  }, []);

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, fontFamily: "Playfair Display", overflow: "hidden" }}>
      
      {/* 
        STAGE BACKGROUND & TRANSPARENT PORTRAIT FRAME
        Uses a massive box-shadow to create the opaque "wall" while leaving the center perfectly transparent.
      */}
      <div style={{
        position: 'absolute',
        left: 290,
        top: 240,
        width: 500,
        height: 600,
        boxShadow: `0 0 0 2000px ${wallColor}`,
        border: `18px solid ${frameBorderColor}`,
        outline: `6px solid ${goldAccent}`,
        outlineOffset: '-6px',
        boxSizing: 'border-box',
        zIndex: 1
      }} />

      {/* LEFT CURTAIN */}
      <div style={{ 
        position: 'absolute', 
        width: 540, 
        height: 1080, 
        filter: 'drop-shadow(15px 0 20px rgba(0,0,0,0.7))',
        zIndex: 10 
      }}>
        <div style={{ 
          clipPath: `path('${leftPath}')`, 
          width: 1080, // Allow stretch for path calculation
          height: 1080 
        }}>
          <div style={{ 
            background: curtainGrad, 
            width: 540, 
            height: 1080, 
            transform: `scaleX(${innerScaleX})`, 
            transformOrigin: 'left top' 
          }} />
        </div>
      </div>

      {/* LEFT TIEBACK */}
      <div style={{
        position: 'absolute',
        left: leftX_tie - 60,
        top: 590,
        width: 80,
        height: 25,
        background: `linear-gradient(to bottom, ${goldAccent}, #aa8000, ${goldAccent})`,
        borderRadius: 12,
        transform: 'rotate(20deg)',
        boxShadow: '0 5px 10px rgba(0,0,0,0.5)',
        opacity: p * 2, // Fades in quickly as it opens
        zIndex: 15
      }} />

      {/* RIGHT CURTAIN */}
      <div style={{ 
        position: 'absolute', 
        left: 0,
        width: 1080, 
        height: 1080, 
        filter: 'drop-shadow(-15px 0 20px rgba(0,0,0,0.7))',
        zIndex: 10 
      }}>
        <div style={{ 
          clipPath: `path('${rightPath}')`, 
          width: 1080, 
          height: 1080 
        }}>
          <div style={{ 
            position: 'absolute',
            left: 540,
            background: curtainGrad, 
            width: 540, 
            height: 1080, 
            transform: `scaleX(${innerScaleX})`, 
            transformOrigin: 'right top' 
          }} />
        </div>
      </div>

      {/* RIGHT TIEBACK */}
      <div style={{
        position: 'absolute',
        left: rightX_tie - 20,
        top: 590,
        width: 80,
        height: 25,
        background: `linear-gradient(to bottom, ${goldAccent}, #aa8000, ${goldAccent})`,
        borderRadius: 12,
        transform: 'rotate(-20deg)',
        boxShadow: '0 5px 10px rgba(0,0,0,0.5)',
        opacity: p * 2,
        zIndex: 15
      }} />

      {/* TOP DRAPE / VALANCE (Frilly & Pleated) */}
      <svg style={{ 
        position: 'absolute', 
        top: -10, 
        left: 0, 
        width: 1080, 
        height: 300, 
        filter: 'drop-shadow(0 15px 25px rgba(0,0,0,0.8))', 
        zIndex: 20 
      }}>
        {/* Back/Darker Scallops */}
        <path d="M 0 0 L 0 140 Q 90 250, 180 140 Q 270 250, 360 140 Q 450 250, 540 140 Q 630 250, 720 140 Q 810 250, 900 140 Q 990 250, 1080 140 L 1080 0 Z" fill={curtainDark} />
        
        {/* Front/Lighter Scallops */}
        <path d="M 0 0 L 0 110 Q 90 210, 180 110 Q 270 210, 360 110 Q 450 210, 540 110 Q 630 210, 720 110 Q 810 210, 900 110 Q 990 210, 1080 110 L 1080 0 Z" fill={curtainPrimary} />
        
        {/* Gold Fringe Edge */}
        <path d="M 0 110 Q 90 210, 180 110 Q 270 210, 360 110 Q 450 210, 540 110 Q 630 210, 720 110 Q 810 210, 900 110 Q 990 210, 1080 110" fill="none" stroke={goldAccent} strokeWidth="12" strokeLinecap="round" strokeLinejoin="round" />

        {/* Pleat Lines (Darker inner folds at the joints) */}
        <path d="M 180 110 L 180 0 M 360 110 L 360 0 M 540 110 L 540 0 M 720 110 L 720 0 M 900 110 L 900 0" fill="none" stroke={curtainDark} strokeWidth="16" opacity="0.6" />
        <path d="M 180 110 L 180 0 M 360 110 L 360 0 M 540 110 L 540 0 M 720 110 L 720 0 M 900 110 L 900 0" fill="none" stroke="#000" strokeWidth="6" opacity="0.3" />

        {/* Highlight Pleat Lines (Center of the scallops) */}
        <path d="M 90 200 L 90 0 M 270 200 L 270 0 M 450 200 L 450 0 M 630 200 L 630 0 M 810 200 L 810 0 M 990 200 L 990 0" fill="none" stroke="#fff" strokeWidth="12" opacity="0.1" />
      </svg>

      {/* MARQUEE SIGN */}
      <div style={{
        position: 'absolute',
        bottom: 40,
        left: 160,
        width: 760,
        height: 260,
        backgroundColor: marqueePrimary,
        borderRadius: 30,
        boxShadow: '0 15px 40px rgba(0,0,0,0.7), 0 0 50px rgba(255, 223, 0, 0.3)', // Backlit glow effect
        transform: `translateY(${marqueeTranslateY}px)`,
        zIndex: 30,
        border: `8px solid ${goldAccent}`,
        boxSizing: 'border-box'
      }}>
        {/* Inner blank panel (No words, as requested) */}
        <div style={{
          position: 'absolute',
          top: 35, 
          left: 35, 
          right: 35, 
          bottom: 35,
          backgroundColor: marqueeInner,
          borderRadius: 15,
          boxShadow: 'inset 0 0 30px rgba(0,0,0,0.4), inset 0 0 8px rgba(0,0,0,0.6)'
        }} />
        
        {/* Perimeter Flashing Bulbs */}
        {bulbs.map((b, i) => (
          <Bulb key={i} x={b.x} y={b.y} index={i} frame={frame} />
        ))}
      </div>

    </AbsoluteFill>
  );
};

export default TheaterReveal;